<?php if(!defined('ABSPATH'))exit; ?><!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php bloginfo('name'); ?></title><?php wp_head(); ?></head><body <?php body_class(); ?>><?php wp_body_open(); ?>
<header class="header"><div class="container"><a class="brand" href="<?php echo esc_url(home_url('/')); ?>"><?php bloginfo('name'); ?></a><nav class="nav"><a href="<?php echo esc_url(home_url('/')); ?>">Home</a><?php foreach (get_categories(array('hide_empty'=>true,'number'=>6)) as $cat): ?><a href="<?php echo esc_url(get_category_link($cat->term_id)); ?>"><?php echo esc_html($cat->name); ?></a><?php endforeach; ?></nav></div></header>
<main><section class="hero"><div class="container hero-grid"><div><span class="kicker">Blog & Magazine</span><h1><?php echo esc_html(get_bloginfo('description') ?: 'Ideas worth reading. Stories worth sharing.'); ?></h1><p>Publish useful stories, guides and ideas with a clean editorial layout. Everything below comes from your WordPress content.</p></div><div class="cover"><div><span class="kicker">Latest post</span><?php $featured = new WP_Query(array('posts_per_page'=>1,'post_status'=>'publish')); if($featured->have_posts()): while($featured->have_posts()): $featured->the_post(); ?><strong><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></strong><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),18)); ?></p><?php endwhile; wp_reset_postdata(); else: ?><strong>Add your first post</strong><p>Your latest published article will appear here automatically.</p><?php endif; ?></div></div></div></section>
<section class="stories" id="stories"><div class="container"><div class="section-title"><h2>Latest stories</h2><span><?php echo esc_html(wp_count_posts()->publish); ?> published</span></div><?php $posts = new WP_Query(array('posts_per_page'=>8,'post_status'=>'publish','ignore_sticky_posts'=>true)); if($posts->have_posts()): while($posts->have_posts()): $posts->the_post(); ?><article class="story"><div class="tag"><?php $cats=get_the_category(); if($cats) echo esc_html($cats[0]->name); ?></div><div><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),24)); ?></p><div class="post-tags"><?php the_tags('', ' · ', ''); ?></div></div><div class="date"><?php echo esc_html(get_the_date('F j, Y')); ?></div></article><?php endwhile; else: ?><div class="empty">No published posts yet. Create one from Posts → Add New.</div><?php endif; wp_reset_postdata(); ?></div></section>
<section class="stories" id="about"><div class="container"><div class="section-title"><h2>Categories</h2><span>Browse topics</span></div><div class="category-grid"><?php foreach(get_categories(array('hide_empty'=>true)) as $cat): ?><a class="category-card" href="<?php echo esc_url(get_category_link($cat->term_id)); ?>"><strong><?php echo esc_html($cat->name); ?></strong><span><?php echo esc_html($cat->count); ?> posts</span></a><?php endforeach; ?></div><div class="section-title tags-title"><h2>Tags</h2><span>Explore keywords</span></div><div class="tag-cloud"><?php wp_tag_cloud(array('smallest'=>12,'largest'=>20,'unit'=>'px','number'=>30)); ?></div></div></section></main>
<footer class="footer"><div class="container">© <?php echo date('Y'); ?> <?php bloginfo('name'); ?> · Built for thoughtful publishing.</div></footer><?php wp_footer(); ?></body></html>